INSERT INTO `travel_plan` (`id`, `user_id`, `title`, `destination`, `start_date`, `end_date`, `plan_data`, `is_public`, `create_time`) VALUES
('4', '24', '杭州慢韵·三日出走', '浙江杭州', '2026-06-03', '2026-06-05', '[{"day": 1, "tips": "西湖边蚊虫较多，请携带驱蚊液；楼外楼建议提前电话预约靠窗位。", "foods": ["西湖醋鱼", "东坡肉", "知味小笼", "猫耳朵"], "items": ["上午9:00从断桥残雪起步，沿白堤缓行至孤山，欣赏平湖秋月、放鹤亭，感受西湖古典韵味，慢走约1小时。", "上午10:30进入孤山脚下的浙江省博物馆（孤山馆区），重点参观越地长歌展区，了解吴越文化，约1.5小时。", "中午12:30在楼外楼（孤山路30号）品尝西湖醋鱼和东坡肉，坐在临窗位置看西湖波光，搭配龙井茶解腻。", "下午14:00从孤山步行至苏堤北端，选花港观鱼段散步，看红鲤与牡丹亭，中途在长桥边小坐20分钟放空。", "下午17:00前往湖滨银泰in77的‘知味观’吃晚餐，点一份知味小笼和猫耳朵，感受杭州老字号手艺。", "晚上19:00沿湖滨路步行至西湖音乐喷泉（视开放情况），看灯光水舞，然后从集贤亭折返，结束第一日。"], "notes": "", "theme": "西湖东线与湖滨风情", "museums": ["浙江省博物馆（孤山馆区）"], "classicPlaces": ["断桥残雪", "白堤", "孤山", "苏堤", "花港观鱼", "湖滨"]}, {"day": 2, "tips": "灵隐寺需提前预约门票（微信小程序''杭州灵隐''）；满觉陇傍晚打车较难，建议提前叫车。", "foods": ["龙井虾仁", "葱包桧", "定胜糕", "片儿川"], "items": ["上午8:00从龙翔桥乘7路到灵隐站，8:30入灵隐寺，先参观天王殿、大雄宝殿，再登飞来峰看石刻造像，静心约2小时。", "上午10:30出灵隐寺沿天竺路步行至法喜寺，途中买一碗素面（5元素面）做早点，进法喜寺拜观音，摸御碑。", "中午12:00在法喜寺旁‘江南驿’餐厅用午餐，点一份龙井虾仁和葱包桧，窗外是茶园风景，清淡鲜美。", "下午14:00乘公交至中国茶叶博物馆（双峰馆区），在馆内品茶体验区喝一杯明前龙井，学习绿茶炒制工艺，约1.5小时。", "下午17:00沿龙井路步行至满觉陇，路过杨梅岭村，在‘茶人村’吃晚餐，点一份定胜糕和片儿川，感受农家风味。", "晚上19:00从满觉陇骑行或打车回市区，在武林夜市慢逛，尝一块新鲜出炉的定胜糕，买几盒龙井茶做手信。"], "notes": "", "theme": "灵隐禅踪与龙井茶香", "museums": ["中国茶叶博物馆（双峰馆区）"], "souvenirs": ["龙井茶"], "classicPlaces": ["灵隐寺", "飞来峰", "法喜寺", "龙井路", "满觉陇"]}, {"day": 3, "tips": "水上巴士需刷杭州通卡或支付宝扫码，建议提前充值；河坊街晚餐需避开19点高峰，提前取号。", "foods": ["片儿川", "桂花拿铁", "定胜糕", "西湖醋鱼", "东坡肉", "干炸响铃"], "items": ["上午9:00从武林门码头乘水上巴士1号线至拱宸桥站，船行约30分钟，沿途看运河两岸杨柳与老厂房。", "上午9:40上拱宸桥，步行至桥西历史街区，参观杭州工艺美术博物馆（伞、扇、刀剪剑分馆），体验手作约1.5小时。", "中午12:00在小河直街的‘老桥头面馆’吃午餐，点一碗片儿川加荷包蛋，搭配自家卤鸭，汤鲜面劲。", "下午13:30逛小河直街茶馆，选一家‘井咖啡’喝桂花拿铁，沿街看老杭州民居、晒台晾衣，慢走1小时。", "下午15:30乘公交至南宋御街，从鼓楼入口一路向南，看古城墙遗址、凤凰寺，在‘定胜糕大叔’摊买刚蒸出的定胜糕。", "晚上18:00在河坊街‘皇饭儿’吃晚餐，点西湖醋鱼和东坡肉，再叫一份干炸响铃，餐后逛胡庆余堂药铺，买几盒八珍糕作伴手礼。"], "notes": "", "theme": "运河老街与市井漫步", "museums": ["杭州工艺美术博物馆（伞、扇、刀剪剑分馆）"], "souvenirs": ["八珍糕"], "classicPlaces": ["拱宸桥", "桥西历史街区", "小河直街", "南宋御街", "河坊街"]}]', '0', '2026-06-12 06:30:39'),
('5', '20', '大兴安岭雪境慢旅·寻北极光美食5日', '黑龙江大兴安岭', '2027-01-08', '2027-01-12', '[{"day": 1, "tips": "漠河冬季气温常低于-30℃，务必穿戴羽绒服、雪地靴、帽子手套；建议提前预订接机服务，避免露天等车。", "foods": ["铁锅炖大鹅", "杀猪菜", "冻梨"], "items": ["上午：抵达漠河古莲机场，乘坐机场大巴（约30分钟）前往漠河市区，入住北极村附近酒店，安顿行李并适应寒冷气候，避免剧烈活动。", "中午：在漠河市区的『老东北铁锅炖』品尝铁锅炖大鹅，搭配玉米饼和酸菜，体验柴火慢炖的浓郁滋味，暖身开胃。", "下午：步行前往松苑公园，观赏原始森林中的雪松与白桦，拍照留念；随后参观五六火灾纪念馆（免费，16:30闭馆），了解1987年大火历史，感受城市重生。", "傍晚：漫步漠河街头的『北极星广场』，登高俯瞰日落中的小镇雪景，再前往『北北家』餐厅品尝杀猪菜、血肠和自制冻梨，感受地道年味。", "晚上：返回酒店，用热水泡脚驱寒；提前预约明天前往北极村的包车（约200元/趟），并确认极光预报信息（若天气晴好可留意深夜极光）。"], "notes": "", "theme": "漠河初雪与城市慢行", "museums": ["五六火灾纪念馆"], "souvenirs": [], "classicPlaces": ["松苑公园", "五六火灾纪念馆", "北极星广场"]}, {"day": 2, "tips": "北极村驯鹿园需步行雪地，建议穿冰爪防滑；火炕房间干燥，睡前多喝水，备好润唇膏。", "foods": ["锅包肉", "小鸡炖蘑菇", "酸菜猪肉饺子", "冻柿子"], "items": ["上午：从漠河市区包车（50分钟）至北极村，入住特色木刻楞民宿；首先徒步参观『最北邮局』，寄出一张盖有最北邮戳的明信片给亲友，纪念意义独特。", "中午：在『北极人家』享用午餐，必点锅包肉（外酥里嫩）、粘豆包蘸白糖，搭配一碗热乎的小鸡炖蘑菇，补充能量。", "下午：前往鄂温克驯鹿园（门票30元），近距离喂食驯鹿，了解鄂温克族使鹿文化，在雪地中与温顺的鹿合影；之后沿『北极沙洲』栈道行走，寻找『神州北极』石碑和『金鸡之冠』。", "傍晚：在北极村主街的『最北饺子馆』吃酸菜猪肉馅饺子，搭配蒜泥和醋，晚来一碗冻柿子；餐后漫步村中，欣赏璀璨星空，若运气好可见极光舞动。", "晚上：回木刻楞民宿，体验东北火炕，室内温度宜人；可让民宿老板帮忙烤土豆、烤地瓜作为宵夜，感受地道农家夜话。"], "notes": "", "theme": "北极村寻北与驯鹿之约", "museums": [], "souvenirs": ["最北邮局明信片"], "classicPlaces": ["最北邮局", "北极沙洲", "神州北极石碑"]}, {"day": 3, "tips": "龙江第一湾观景台台阶较陡且积雪，务必抓稳扶手慢行；北红村住宿条件较简陋，建议自备洗漱用品和拖鞋。", "foods": ["黑龙江冷水鱼炖豆腐", "大拉皮", "猪肉炖粉条", "地三鲜"], "items": ["上午：从北极村包车（约1.5小时）前往乌苏里浅滩（中国最北点），打卡『北国擎天』石碑，在黑龙江冰面上感受国境线之北的壮阔，注意防寒。", "中午：在龙江第一湾景区内的『第一湾渔家』用餐，推荐品尝黑龙江冷水鱼炖豆腐（鱼肉鲜嫩）、大拉皮（凉爽开胃），背景是冰封的黑龙江湾道。", "下午：登观景台俯瞰龙江第一湾全景（需攀登888级木栈道，慢行约40分钟），银装素裹的Ω形河湾尽收眼底；之后驱车至北红村，入住当地民宿，体验更原始的木楞房。", "傍晚：在北红村内散步，探访最北哨所和北红村小学，感受静谧的边境村庄；晚餐在『北红人家』吃猪肉炖粉条、地三鲜，喝一碗热乎乎的酸菜汤。", "晚上：参与民宿举办的篝火晚会（视天气和人数），烤火、聊天、仰望银河；回房后用热水袋暖足，为次日雪地徒步储备体力。"], "notes": "", "theme": "龙江第一湾与北红村秘境", "museums": [], "souvenirs": [], "classicPlaces": ["乌苏里浅滩", "龙江第一湾", "北红村", "最北哨所"]}, {"day": 4, "tips": "九曲十八弯观景台风大，建议佩戴防风面罩；购买山货时注意称重和封装，可在当地特产店索取真空包装便于携带。", "foods": ["漠河烤鱼", "铁锅炖排骨豆角", "薄荷糖醋排骨"], "items": ["上午：从北红村出发，包车返回漠河市区，途中在『九曲十八弯』景区停留（门票50元），登上观景台俯瞰额木尔河蜿蜒雪原，视野开阔，适合拍摄晨雾。", "中午：驱车至漠河市区附近的『飞虎山』雪地徒步点（免费），在没膝深的雪原中行走约1小时，穿白桦林、听踩雪声，完后返回市区。", "下午：在漠河市区的『鼎峰餐厅』用午餐，点特色菜『薄荷糖醋排骨』、『东北大丰收』（炖玉米、豆角、南瓜），还有招牌『漠河烤鱼』，弥补未吃够的遗憾。", "傍晚：逛『漠河老街基』步行街，购买野生蓝莓干、蔓越莓干、漠河木耳、榛子等山货作为伴手礼；晚餐再吃一顿『铁锅炖』，可选排骨豆角锅，加贴饼子。", "晚上：返回漠河市区酒店，整理行李，可去『北极星浴场』（非必去）体验一次东北搓澡，驱散多日疲劳；早睡，为次日返程养精蓄锐。"], "notes": "", "theme": "白桦林穿越与漠河美食终章", "museums": [], "souvenirs": ["野生蓝莓干", "蔓越莓干", "漠河木耳", "榛子"], "classicPlaces": ["九曲十八弯", "飞虎山", "漠河老街基"]}, {"day": 5, "tips": "漠河机场较小，建议提前1小时到达即可；随身携带保温杯装满热水，飞机上饮用可避免干燥。", "foods": ["豆腐脑", "酸菜炖粉条", "血肠拼盘", "北极村文创雪糕"], "items": ["上午：睡到自然醒，在漠河市区找一家『老式烧饼店』吃早餐，豆腐脑配酥皮烧饼，再喝一杯热豆浆，感受小城慢节奏。", "中午：前往『松苑公园』补拍晨雪照片，然后去『漠河极地体验馆』（免费，约30分钟）观看极光模拟展，了解极光成因。", "午餐：在漠河机场附近的『雪乡人家』最后一顿，推荐『酸菜炖粉条』、『血肠拼盘』和『冻梨汁』，回味大兴安岭的味道。", "下午：提前2小时到达漠河古莲机场，办理登机手续，托运伴手礼；在候机厅购买『北极村文创雪糕』（造型如北极哨所），作为旅途终点的小趣味。", "傍晚：登机离开，结束5天慢节奏山野美食之旅，期待下次与极光重逢。"], "notes": "", "theme": "慢行收尾与返程", "museums": ["漠河极地体验馆"], "souvenirs": ["北极村文创雪糕（拍照后食用）"], "classicPlaces": ["松苑公园", "漠河极地体验馆"]}]', '1', '2026-06-14 05:45:57');
